  'games.prompt.listenQuality': { 'en-US': 'Listen to the chord quality (played on {instrument})', 'vi-VN': 'Nghe màu hợp âm (chơi bằng {instrument})', 'zh-CN': '听和弦性质（用{instrument}演奏）', 'ja-JP': 'コードの性質を聴く（{instrument}）', 'ko-KR': '코드 성질을 듣기 ({instrument})' },
  'games.prompt.referenceScale': { 'en-US': 'Reference scale: {scale} ascending and descending, then a mystery note. Identify the scale degree (played on {instrument})', 'vi-VN': 'Thang chuẩn: {scale} đi lên rồi đi xuống, sau đó một nốt bí ẩn. Xác định bậc (chơi bằng {instrument})', 'zh-CN': '参考音阶：{scale} 上行再下行，然后一个未知音。判断级数（用{instrument}演奏）', 'ja-JP': '基準音階: {scale} を上行・下行したあと、未知の音。度数を答える（{instrument}）', 'ko-KR': '기준 음계: {scale}을 오르내린 뒤 미지의 음. 도수를 맞히기 ({instrument})' },
  'games.prompt.identifyProgression': { 'en-US': 'Tonic reference chord ({scale}) will be played first, then the sequence. Identify the progression (played on {instrument}):', 'vi-VN': 'Hợp âm chủ chuẩn ({scale}) được chơi trước, rồi đến chuỗi hợp âm. Nhận tiến trình (chơi bằng {instrument}):', 'zh-CN': '先演奏主和弦参考（{scale}），再演奏序列。判断进行（用{instrument}演奏）：', 'ja-JP': '最初に主和音（{scale}）が鳴り、そのあと進行です。進行を答えてください（{instrument}）:', 'ko-KR': '으뜸 화음({scale})이 먼저 들리고 그다음 진행이 나옵니다. 진행을 맞히세요 ({instrument}):' },
  'games.prompt.identifyTonicization': { 'en-US': 'Tonic reference chord ({scale}) will be played first, then the sequence. Identify the tonicization progression (played on {instrument}):', 'vi-VN': 'Hợp âm chủ chuẩn ({scale}) được chơi trước, rồi đến chuỗi hợp âm. Nhận tiến trình tonic hóa (chơi bằng {instrument}):', 'zh-CN': '先演奏主和弦参考（{scale}），再演奏序列。判断临时主音化进行（用{instrument}演奏）：', 'ja-JP': '最初に主和音（{scale}）が鳴り、そのあと進行です。トニシゼーションを答えてください（{instrument}）:', 'ko-KR': '으뜸 화음({scale})이 먼저 들리고 그다음 진행이 나옵니다. 일시적 으뜸화를 맞히세요 ({instrument}):' },
  'games.prompt.modeFormula': { 'en-US': 'What is the interval formula for {mode} mode, given W is whole step and H is half step? (Hint: The Ionian mode formula is W - W - H - W - W - W - H. Think about rotating the sequence to the left and wrapping around.)', 'vi-VN': 'Công thức quãng của mode {mode} là gì, với W là cung trưởng và H là nửa cung? (Gợi ý: công thức Ionian là W - W - H - W - W - W - H. Hãy xoay dãy sang trái và vòng lại.)', 'zh-CN': '{mode} 调式的音程公式是什么？W 是全音，H 是半音。（提示：伊奥尼亚公式是 W - W - H - W - W - W - H。把序列向左旋转并绕回。）', 'ja-JP': '{mode} モードの音程式は何ですか。W は全音、H は半音です。（ヒント: イオニアンは W - W - H - W - W - W - H。列を左へ回して先頭へ戻します。）', 'ko-KR': 'W는 온음, H는 반음일 때 {mode} 모드의 음정 공식은 무엇입니까? (힌트: 이오니안 공식은 W - W - H - W - W - W - H. 수열을 왼쪽으로 돌려 처음으로 돌아오세요.)' },
  'games.prompt.modeNote': { 'en-US': 'What is the {ordinal} note in {tonic} {mode} mode?', 'vi-VN': 'Nốt {ordinal} của mode {mode} giọng {tonic} là nốt nào?', 'zh-CN': '{tonic} {mode} 调式的{ordinal}个音是什么？', 'ja-JP': '{tonic} の {mode} モードで {ordinal} の音は何ですか？', 'ko-KR': '{tonic} {mode} 모드의 {ordinal} 음은 무엇입니까?' },
  'games.explain.modeIonian': { 'en-US': 'The Ionian mode (major scale) is the 1st mode, so its formula remains the default: W - W - H - W - W - W - H.', 'vi-VN': 'Mode Ionian (thang trưởng) là mode thứ 1, nên công thức giữ nguyên mặc định: W - W - H - W - W - W - H.', 'zh-CN': '伊奥尼亚调式（大调）是第 1 调式，公式保持默认：W - W - H - W - W - W - H。', 'ja-JP': 'イオニアン（長音階）は 1 番目のモードなので、式はそのままです: W - W - H - W - W - W - H。', 'ko-KR': '이오니안(장음계)은 1번째 모드이므로 공식은 기본 그대로입니다: W - W - H - W - W - W - H.' },
  'games.explain.modeRotate': { 'en-US': 'The {mode} mode is the {ordinal} mode of the major scale. To find its formula, we rotate the Ionian formula (W - W - H - W - W - W - H) to the left by {steps} and wrap around:\n', 'vi-VN': 'Mode {mode} là mode {ordinal} của thang trưởng. Để tìm công thức, xoay công thức Ionian (W - W - H - W - W - W - H) sang trái {steps} và vòng lại:\n', 'zh-CN': '{mode} 是大调的{ordinal}调式。把伊奥尼亚公式（W - W - H - W - W - W - H）向左旋转 {steps} 并绕回，就得到它的公式：\n', 'ja-JP': '{mode} は長音階の {ordinal} モードです。イオニアンの式（W - W - H - W - W - W - H）を左へ {steps} 回して先頭に戻します:\n', 'ko-KR': '{mode}는 장음계의 {ordinal} 모드입니다. 이오니안 공식(W - W - H - W - W - W - H)을 왼쪽으로 {steps} 돌려 처음으로 돌아오면 됩니다:\n' },
  'games.explain.modeNote': { 'en-US': 'The notes in {tonic} {mode} are {notes}. The {ordinal} note is {answer}.', 'vi-VN': 'Các nốt của {mode} giọng {tonic} là {notes}. Nốt {ordinal} là {answer}.', 'zh-CN': '{tonic} {mode} 的音是 {notes}。{ordinal}个音是 {answer}。', 'ja-JP': '{tonic} の {mode} の音は {notes} です。{ordinal} の音は {answer} です。', 'ko-KR': '{tonic} {mode}의 음은 {notes}입니다. {ordinal} 음은 {answer}입니다.' },
