  'docs.title': { 'en-US': 'ChordMini API Documentation', 'vi-VN': 'Tài liệu API ChordMini', 'zh-CN': 'ChordMini API 文档', 'ja-JP': 'ChordMini API ドキュメント', 'ko-KR': 'ChordMini API 문서' },
  'docs.intro': { 'en-US': 'A comprehensive guide to using our audio analysis API, covering beat detection, chord recognition, and more.', 'vi-VN': 'Hướng dẫn dùng API phân tích âm thanh, gồm nhận nhịp, nhận hợp âm và các phần khác.', 'zh-CN': '使用音频分析 API 的完整指南，涵盖节拍检测、和弦识别等。', 'ja-JP': 'ビート検出やコード認識などを含む、音声解析 API の使い方です。', 'ko-KR': '비트 감지와 코드 인식을 포함한 오디오 분석 API 사용 안내입니다.' },
  'docs.gettingStarted': { 'en-US': 'Getting Started', 'vi-VN': 'Bắt đầu', 'zh-CN': '入门', 'ja-JP': 'はじめに', 'ko-KR': '시작하기' },
  'docs.gettingBody': { 'en-US': 'The ChordMini API provides powerful audio analysis capabilities with no authentication required. Start making requests immediately to analyze audio files and extract musical information.', 'vi-VN': 'API ChordMini phân tích âm thanh và, theo tài liệu này, không yêu cầu xác thực. Có thể gửi yêu cầu ngay để phân tích tệp và lấy thông tin nhạc.', 'zh-CN': 'ChordMini API 提供音频分析能力，本文档记载它不需要身份验证。可以立即请求以分析音频并提取音乐信息。', 'ja-JP': 'ChordMini API は音声を解析します。この文書では認証不要と記載しています。すぐにリクエストして音楽情報を取り出せます。', 'ko-KR': 'ChordMini API는 오디오를 분석합니다. 이 문서는 인증이 필요 없다고 적습니다. 바로 요청해 음악 정보를 얻을 수 있습니다.' },
  'docs.beatTitle': { 'en-US': 'Beat Detection', 'vi-VN': 'Nhận nhịp', 'zh-CN': '节拍检测', 'ja-JP': 'ビート検出', 'ko-KR': '비트 감지' },
  'docs.beatBody': { 'en-US': 'Identify beat positions and downbeats using advanced ML models.', 'vi-VN': 'Xác định vị trí nhịp và phách mạnh bằng các mô hình học máy.', 'zh-CN': '用机器学习模型识别节拍位置和强拍。', 'ja-JP': '機械学習モデルで拍の位置と強拍を見つけます。', 'ko-KR': '기계 학습 모델로 박 위치와 강박을 찾습니다.' },
  'docs.chordTitle': { 'en-US': 'Chord Recognition', 'vi-VN': 'Nhận hợp âm', 'zh-CN': '和弦识别', 'ja-JP': 'コード認識', 'ko-KR': '코드 인식' },
  'docs.chordBody': { 'en-US': 'Recognize chord progressions with multiple model options.', 'vi-VN': 'Nhận tiến trình hợp âm với nhiều lựa chọn mô hình.', 'zh-CN': '用多种模型识别和弦进行。', 'ja-JP': '複数のモデルでコード進行を認識します。', 'ko-KR': '여러 모델로 코드 진행을 인식합니다.' },
  'docs.lyricsTitle': { 'en-US': 'Lyrics Fetching', 'vi-VN': 'Lấy lời bài hát', 'zh-CN': '获取歌词', 'ja-JP': '歌詞の取得', 'ko-KR': '가사 가져오기' },
  'docs.lyricsBody': { 'en-US': 'Retrieve synchronized lyrics from LRClib database.', 'vi-VN': 'Lấy lời đồng bộ từ cơ sở dữ liệu LRClib.', 'zh-CN': '从 LRClib 数据库获取同步歌词。', 'ja-JP': 'LRClib から同期歌詞を取得します。', 'ko-KR': 'LRClib 데이터베이스에서 동기화된 가사를 가져옵니다.' },
  'docs.modelInfoTitle': { 'en-US': 'Model Info', 'vi-VN': 'Thông tin mô hình', 'zh-CN': '模型信息', 'ja-JP': 'モデル情報', 'ko-KR': '모델 정보' },
  'docs.modelInfoBody': { 'en-US': 'Get details about available models and capabilities.', 'vi-VN': 'Xem chi tiết các mô hình và khả năng hiện có.', 'zh-CN': '查看可用模型及其能力。', 'ja-JP': '利用できるモデルと機能の詳細を取得します。', 'ko-KR': '사용할 수 있는 모델과 기능의 세부 정보를 봅니다.' },
  'docs.authTitle': { 'en-US': 'Authentication', 'vi-VN': 'Xác thực', 'zh-CN': '身份验证', 'ja-JP': '認証', 'ko-KR': '인증' },
  'docs.noKeyTitle': { 'en-US': 'Documented: no API key required', 'vi-VN': 'Trong tài liệu: không cần khóa API', 'zh-CN': '文档记载：不需要 API 密钥', 'ja-JP': '文書上の記載: API キーは不要', 'ko-KR': '문서상 기재: API 키 불필요' },
  'docs.noKeyBody': { 'en-US': 'This page documents the public ChordMini API as not requiring authentication. It is not a live check that every endpoint is open.', 'vi-VN': 'Trang này ghi rằng API công khai của ChordMini không yêu cầu xác thực. Đây không phải kiểm tra trực tiếp rằng mọi điểm cuối đang mở.', 'zh-CN': '本页把公开的 ChordMini API 记载为无需身份验证。这不是对每个端点是否开放的实时检查。', 'ja-JP': 'このページは、公開 ChordMini API を認証不要と記載しています。すべてのエンドポイントが開いていることのライブ確認ではありません。', 'ko-KR': '이 페이지는 공개 ChordMini API가 인증을 요구하지 않는다고 적습니다. 모든 엔드포인트가 열려 있는지 실시간으로 확인한 것은 아닙니다.' },
  'docs.futureTitle': { 'en-US': 'Future Changes', 'vi-VN': 'Thay đổi sau này', 'zh-CN': '将来的变化', 'ja-JP': '今後の変更', 'ko-KR': '이후 변경' },
  'docs.futureBody': { 'en-US': 'Authentication may be required in future versions. Implement proper error handling for potential 401/403 responses.', 'vi-VN': 'Các phiên bản sau có thể yêu cầu xác thực. Hãy xử lý lỗi cho phản hồi 401/403.', 'zh-CN': '未来版本可能需要身份验证。请为可能的 401/403 响应做好错误处理。', 'ja-JP': '将来の版では認証が必要になる場合があります。401/403 のエラー処理を用意してください。', 'ko-KR': '이후 버전에서는 인증이 필요할 수 있습니다. 401/403 응답에 대한 오류 처리를 넣으세요.' },
  'docs.ratesTitle': { 'en-US': 'Rate Limits', 'vi-VN': 'Giới hạn tần suất', 'zh-CN': '速率限制', 'ja-JP': 'レート制限', 'ko-KR': '속도 제한' },
  'docs.ratesBody': { 'en-US': 'The ChordMini API implements production-grade rate limiting to ensure fair usage and system stability. Rate limits vary by endpoint based on computational requirements.', 'vi-VN': 'API ChordMini giới hạn tần suất để dùng công bằng và giữ hệ thống ổn định. Giới hạn khác nhau theo điểm cuối và mức tính toán.', 'zh-CN': 'ChordMini API 使用生产级速率限制，以保证公平使用和系统稳定。限制因端点的计算量而不同。', 'ja-JP': 'ChordMini API は公平な利用と安定のためレート制限を使います。制限はエンドポイントの計算量で異なります。', 'ko-KR': 'ChordMini API는 공정한 사용과 안정성을 위해 속도 제한을 둡니다. 제한은 엔드포인트의 계산량에 따라 다릅니다.' },
  'docs.colEndpoint': { 'en-US': 'Endpoint', 'vi-VN': 'Điểm cuối', 'zh-CN': '端点', 'ja-JP': 'エンドポイント', 'ko-KR': '엔드포인트' },
