  'docs.reasonLookup': { 'en-US': 'Lyrics lookup and synchronization', 'vi-VN': 'Tra lời và đồng bộ', 'zh-CN': '歌词查找与同步', 'ja-JP': '歌詞の検索と同期', 'ko-KR': '가사 찾기와 동기화' },
  'docs.modelsTitle': { 'en-US': 'Available Models', 'vi-VN': 'Mô hình hiện có', 'zh-CN': '可用模型', 'ja-JP': '利用できるモデル', 'ko-KR': '사용할 수 있는 모델' },
  'docs.modelsBody': { 'en-US': 'ChordMini provides multiple machine learning models for different audio analysis tasks. Each model is optimized for specific use cases and performance characteristics.', 'vi-VN': 'ChordMini có nhiều mô hình học máy cho các việc phân tích âm thanh khác nhau. Mỗi mô hình được tối ưu cho một cách dùng và một đặc tính hiệu năng.', 'zh-CN': 'ChordMini 为不同的音频分析任务提供多个机器学习模型。每个模型针对特定用途和性能特点做了优化。', 'ja-JP': 'ChordMini には用途の違う機械学習モデルがあります。それぞれ特定の使い方と性能に合わせてあります。', 'ko-KR': 'ChordMini에는 서로 다른 오디오 분석용 기계 학습 모델이 있습니다. 각 모델은 특정 용도와 성능에 맞춰져 있습니다.' },
  'docs.beatModels': { 'en-US': 'Beat Detection Models', 'vi-VN': 'Mô hình nhận nhịp', 'zh-CN': '节拍检测模型', 'ja-JP': 'ビート検出モデル', 'ko-KR': '비트 감지 모델' },
