  'docs.madmomBest': { 'en-US': 'Pop, Rock, Electronic music', 'vi-VN': 'Nhạc pop, rock, điện tử', 'zh-CN': '流行、摇滚、电子音乐', 'ja-JP': 'ポップ、ロック、エレクトロニック', 'ko-KR': '팝, 록, 일렉트로닉' },
  'docs.beatTransformerBody': { 'en-US': 'DL model with 5-channel audio separation, flexible in time signatures, slow processing speed.', 'vi-VN': 'Mô hình học sâu tách âm 5 kênh, linh hoạt với nhịp số, tốc độ xử lý chậm.', 'zh-CN': '带 5 通道音源分离的深度学习模型，拍号灵活，处理较慢。', 'ja-JP': '5 チャンネル分離の深層学習モデル。拍子に柔軟で、処理は遅めです。', 'ko-KR': '5채널 분리 딥러닝 모델. 박자에 유연하고 처리는 느립니다.' },
  'docs.beatTransformerBest': { 'en-US': 'Complex mixes, layered instrumentation', 'vi-VN': 'Bản phối phức tạp, nhiều lớp nhạc cụ', 'zh-CN': '复杂混音、多层乐器', 'ja-JP': '複雑なミックス、重なった楽器', 'ko-KR': '복잡한 믹스, 겹친 악기' },
  'docs.cnnBody': { 'en-US': 'Convolutional and LSTM neural network for chord recognition with 301 chord labels. Excellent balance of accuracy and performance.', 'vi-VN': 'Mạng tích chập và LSTM nhận hợp âm với 301 nhãn. Cân bằng tốt giữa độ chính xác và hiệu năng.', 'zh-CN': '用于和弦识别的卷积和 LSTM 网络，有 301 个和弦标签。准确性和性能比较均衡。', 'ja-JP': '301 のコードラベルを持つ畳み込みと LSTM のネットワーク。精度と性能のバランスが良いです。', 'ko-KR': '301개 코드 레이블의 합성곱과 LSTM 신경망. 정확도와 성능의 균형이 좋습니다.' },
